        if (query != null) {
            query = URLEncoder.encode(query, "UTF-8").replace("+", "%20");
        }

        // Reconstruct the URL
        String encodedUrl = scheme + "://" + authority + path;
        if (query != null) {
            encodedUrl += "?" + query;
