                buf.readUnsignedByte(); // type
                position.set(Position.KEY_DRIVER_UNIQUE_ID, ByteBufUtil.hexDump(buf.readSlice(4)));
                buf.readUnsignedByte(); // checksum
                buf.readUnsignedByte(); // footer
