                    lac = buf.readInt();
                    cid = (int) buf.readLong();
                } else if (type == MSG_WIFI_5 || type == MSG_LBS_3) {
                    lac = buf.readUnsignedShort();
                    cid = (int) buf.readUnsignedInt();
